  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Our integrative approach and team background." />
  <style>
    :root{--bg:#f8f3ec;--accent:#6e4f3a;--muted:#9d8f86;--card:#fff;--accent-2:#b68f6a}
    html,body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:#3b3229}
    .pattern{position:fixed;inset:0;opacity:.14;background-image:url("assets/img/pattern.svg");background-repeat:repeat;z-index:0}
    .wrap{max-width:980px;margin:0 auto;padding:28px}
    header{position:relative;z-index:2;background:transparent;padding-bottom:8px}
    nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap}
